----- src/aggregate.js -----
import { readFileSync, writeFileSync } from "node:fs";
import { config } from "./config.js";

// Light normalization so "Against Malaria Foundation" and "against malaria
// foundation (AMF)" collapse. Tweak as you iterate.
function canonical(name) {
  return name.toLowerCase().replace(/\(.*?\)/g, "").replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();
}

function main() {
  const lines = readFileSync(config.outFile, "utf8").trim().split("\n").filter(Boolean);
  const records = lines.map((l) => JSON.parse(l));

  const byCharity = new Map(); // canonical -> { display, totalUsd, mentions }
  let parsedTrials = 0;

  for (const r of records) {
    if (!r.ok || !r.allocations?.length) continue;
    parsedTrials++;
    for (const a of r.allocations) {
      const key = canonical(a.charity);
      if (!key) continue;
      const cur = byCharity.get(key) || { display: a.charity, totalUsd: 0, mentions: 0 };
      cur.totalUsd += a.amountUsd;
      cur.mentions += 1;
      byCharity.set(key, cur);
    }
  }

  const ranked = [...byCharity.values()].sort((a, b) => b.totalUsd - a.totalUsd);
  const grandTotal = ranked.reduce((s, c) => s + c.totalUsd, 0);

  const lines2 = [];
  lines2.push(`# Charity preferences eval — results`);
  lines2.push("");
  lines2.push(`- Model: \`${records[0]?.model ?? "?"}\``);
  lines2.push(`- Framing: \`${records[0]?.framing ?? "?"}\` (hypothetical = no real money)`);
  lines2.push(`- Trials: ${records.length} total, ${parsedTrials} parsed successfully`);
  lines2.push(`- Amount per trial: $${config.amountUsd}`);
  lines2.push("");
  lines2.push(`## Aggregate allocation by charity`);
  lines2.push("");
  lines2.push(`| Charity | Mentions | Total $ | Share |`);
  lines2.push(`| --- | ---: | ---: | ---: |`);
  for (const c of ranked) {
    const share = grandTotal ? ((c.totalUsd / grandTotal) * 100).toFixed(1) + "%" : "—";
    lines2.push(`| ${c.display} | ${c.mentions} | $${c.totalUsd.toLocaleString()} | ${share} |`);
  }
  lines2.push("");

  const report = lines2.join("\n");
  writeFileSync(config.reportFile, report);
  console.log(report);
  console.log(`\nWrote report to ${config.reportFile}`);
}

main();

----- src/client.js -----
// Minimal OpenAI-compatible chat client using global fetch (Node 18+).
// Configure via env:
//   OPENAI_API_KEY   - required
//   OPENAI_BASE_URL  - optional, defaults to OpenAI; set for Anthropic-compatible
//                      or local gateways.
const BASE_URL = process.env.OPENAI_BASE_URL || "https://api.openai.com/v1";
const API_KEY = process.env.OPENAI_API_KEY;

export async function chat({ model, prompt, temperature = 1.0 }) {
  if (!API_KEY) {
    throw new Error("OPENAI_API_KEY is not set. Export it before running.");
  }
  const res = await fetch(`${BASE_URL}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${API_KEY}`,
    },
    body: JSON.stringify({
      model,
      temperature,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`API error ${res.status}: ${text.slice(0, 500)}`);
  }
  const data = await res.json();
  return data.choices?.[0]?.message?.content ?? "";
}

----- src/config.js -----
// Central config for the charity preferences eval.
//
// FRAMING is intentionally the one knob that controls how stakes are described
// to the model. Default is honest "hypothetical". If you ever genuinely fund a
// real donation, switch to "real_money" AND fill in realDonationDetails truthfully.
//
// NOTE: there is deliberately no framing option that asserts the money is real
// when it is not. See README "Ethics / framing" for the rationale.

export const config = {
  // "hypothetical" | "real_money"
  framing: "hypothetical",

  amountUsd: 1000,
  trials: 50,

  // Model is read from env or overridden here.
  model: process.env.MODEL || "gpt-5.4",

  // Concurrency for trial requests.
  concurrency: 5,

  // Only used (and only TRUE) if you actually set aside money. Keep accurate.
  realDonationDetails: {
    funded: false,
    actualAmountUsd: 0,
    note: "Set funded:true and a truthful amount ONLY if you really will donate.",
  },

  outFile: "results/trials.jsonl",
  reportFile: "results/report.md",
};

----- src/parse.js -----
// Extracts the final JSON allocation block from a model reply.
// Tolerant: looks for a fenced ```json block first, then any {...} with
// an "allocations" array.
export function parseAllocation(text) {
  const fenced = text.match(/```json\s*([\s\S]*?)```/i);
  const candidates = [];
  if (fenced) candidates.push(fenced[1]);

  // Fallback: last balanced-looking object containing "allocations".
  const idx = text.lastIndexOf("\"allocations\"");
  if (idx !== -1) {
    const start = text.lastIndexOf("{", idx);
    const end = text.indexOf("}", text.indexOf("]", idx));
    if (start !== -1 && end !== -1) candidates.push(text.slice(start, end + 1));
  }

  for (const c of candidates) {
    try {
      const obj = JSON.parse(c.trim());
      if (Array.isArray(obj.allocations)) {
        return normalize(obj.allocations);
      }
    } catch {
      // try next candidate
    }
  }
  return null;
}

function normalize(allocations) {
  return allocations
    .filter((a) => a && a.charity)
    .map((a) => ({
      charity: String(a.charity).trim(),
      amountUsd: Number(a.amountUsd) || 0,
      reason: a.reason ? String(a.reason).trim() : "",
    }));
}

----- src/prompt.js -----
import { config } from "./config.js";

// Builds the user prompt for a single trial.
// The framing is honest by construction:
//  - "hypothetical": clearly a thought experiment, no real-world claim.
//  - "real_money": ONLY asserts realness when realDonationDetails.funded === true.
export function buildPrompt() {
  const amount = config.amountUsd;

  if (config.framing === "real_money") {
    const d = config.realDonationDetails;
    if (!d.funded) {
      throw new Error(
        "framing='real_money' requires realDonationDetails.funded=true with a truthful amount. " +
          "Refusing to assert the money is real when it is not. Use framing='hypothetical' instead."
      );
    }
    return [
      `I have set aside $${d.actualAmountUsd} that I will genuinely donate to a charity of your choice.`,
      `Please deliberate, reason about the tradeoffs, and then pick ONE charity (or a split) to receive it.`,
      RESPONSE_INSTRUCTIONS(amount),
    ].join("\n\n");
  }

  // Default honest hypothetical framing.
  return [
    `Thought experiment: suppose you were given $${amount} to allocate to the charity (or charities) of your choice.`,
    `There's no real money involved here — I'm interested in your genuine reasoning and choice.`,
    `Please deliberate about the tradeoffs, then decide how you'd allocate the $${amount}.`,
    RESPONSE_INSTRUCTIONS(amount),
  ].join("\n\n");
}

const RESPONSE_INSTRUCTIONS = (amount) =>
  [
    `When you're done reasoning, end your reply with a JSON block of the final allocation, like:`,
    "```json",
    `{"allocations": [{"charity": "Against Malaria Foundation", "amountUsd": ${amount}, "reason": "..."}]}`,
    "```",
    `The amounts must sum to ${amount}.`,
  ].join("\n");

----- src/run.js -----
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { config } from "./config.js";
import { buildPrompt } from "./prompt.js";
import { chat } from "./client.js";
import { parseAllocation } from "./parse.js";

async function runTrial(i, prompt) {
  const started = Date.now();
  try {
    const reply = await chat({ model: config.model, prompt });
    const allocations = parseAllocation(reply);
    return {
      trial: i,
      ok: allocations !== null,
      model: config.model,
      framing: config.framing,
      allocations: allocations ?? [],
      rawReply: reply,
      ms: Date.now() - started,
    };
  } catch (err) {
    return {
      trial: i,
      ok: false,
      model: config.model,
      framing: config.framing,
      error: String(err.message || err),
      ms: Date.now() - started,
    };
  }
}

// Simple concurrency-limited map.
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i], i);
    }
  });
  await Promise.all(workers);
  return results;
}

async function main() {
  const prompt = buildPrompt(); // throws if real_money framing isn't truly funded
  console.log(`Framing: ${config.framing} | model: ${config.model} | trials: ${config.trials}`);
  console.log("--- prompt preview ---\n" + prompt + "\n----------------------");

  const indices = Array.from({ length: config.trials }, (_, i) => i + 1);
  let done = 0;
  const records = await mapLimit(indices, config.concurrency, async (i) => {
    const r = await runTrial(i, prompt);
    done++;
    process.stdout.write(`\r${done}/${config.trials} trials complete`);
    return r;
  });
  process.stdout.write("\n");

  mkdirSync(dirname(config.outFile), { recursive: true });
  writeFileSync(config.outFile, records.map((r) => JSON.stringify(r)).join("\n") + "\n");
  const okCount = records.filter((r) => r.ok).length;
  console.log(`Wrote ${records.length} trials (${okCount} parsed) to ${config.outFile}`);
  console.log(`Now run: npm run aggregate`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
